selector{
    position: absolute;
    bottom:50px;
    filter: brightness(1.05);
}

.scroll-left{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(-30px, 0, 0);
}

.scroll-right{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, 80px, 0);
}

.scroll-top{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, -80px, 0);
}

.ativo{
		opacity: 1;
    transition: 0.5s all;
    transform: translate3d(0, 0, 0);
}

selector::after {
  content: "";
  display: block;
  width: 100%;
  height: 100%;
  position: absolute;
  bottom: 0;
  left: 0;
  z-index: 2;
  background: linear-gradient(to top, #F9F5F2 0%, rgba(249, 245, 242, 0) 50%);
  pointer-events: none;
}

